int calls = 0; // статическая длительность хранения

void record() {
  int step = 1; // автоматическая длительность хранения
  calls += step;
}
// calls сохраняется между вызовами record().
// Для каждого вызова создаётся свой step, который уничтожается при возврате.

#include <iostream>

int measure_width() {
  std::cout << "measured\n";
  return 80;
}

int scaled_width(int factor) {
  static int base = measure_width();
  return base * factor;
}

int main() {
  int twice = scaled_width(2);
  int three_times = scaled_width(3);
  std::cout << twice << ' ' << three_times << '\n';
}
// measure_width() вызывается один раз; оба вычисления используют готовый base.
// factor — отдельный параметр каждого вызова, base сохраняется между вызовами.
